import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.DtFGJNng.js";const g=JSON.parse('{"title":"Proyek yang sudah berjalan","description":"","frontmatter":{},"headers":[],"relativePath":"proyek-existing.md","filePath":"proyek-existing.md","lastUpdated":1794463556000}'),s={name:"proyek-existing.md"};function r(d,a,l,u,k,o){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="proyek-yang-sudah-berjalan" tabindex="-1">Proyek yang sudah berjalan <a class="header-anchor" href="#proyek-yang-sudah-berjalan" aria-label="Permalink to &quot;Proyek yang sudah berjalan&quot;">​</a></h1><p>Sebagian besar tim memakai deuz di sistem yang sudah punya banyak kode. Kabar baiknya: <strong>kamu tidak perlu mendokumentasikan seluruh sistem dulu.</strong></p><h2 id="prinsipnya-spec-tumbuh-dari-perubahan" tabindex="-1">Prinsipnya: spec tumbuh dari perubahan <a class="header-anchor" href="#prinsipnya-spec-tumbuh-dari-perubahan" aria-label="Permalink to &quot;Prinsipnya: spec tumbuh dari perubahan&quot;">​</a></h2><p>Saat pertama kali dipakai, <code>deuz/specs/</code> kosong. Itu normal. Setiap work yang selesai menggabungkan delta-nya ke sana. Spec untuk satu area baru lengkap setelah area itu beberapa kali diubah, dan justru saat itulah kamu paling membutuhkannya.</p><h2 id="langkah-awal" tabindex="-1">Langkah awal <a class="header-anchor" href="#langkah-awal" aria-label="Permalink to &quot;Langkah awal&quot;">​</a></h2><ol><li><strong>Jalankan <code>/deuz:init</code>.</strong> Arahkan homes ke tempat yang sudah ada. Misalnya <code>design</code> ke folder desain yang sudah dipakai test visual, dan <code>api</code> ke file OpenAPI yang sudah ada.</li><li><strong>Pilih perubahan kecil yang nyata</strong> untuk work pertama, yaitu sesuatu yang memang akan dikerjakan minggu ini. Jangan memilih contoh mainan, dan jangan memilih rewrite besar.</li><li><strong>Tulis delta untuk bagian yang disentuh saja.</strong> Kalau perubahannya menyentuh perilaku yang belum punya spec, lihat bagian berikut.</li></ol><h2 id="baseline-mendokumentasikan-perilaku-yang-sudah-ada" tabindex="-1">Baseline: mendokumentasikan perilaku yang sudah ada <a class="header-anchor" href="#baseline-mendokumentasikan-perilaku-yang-sudah-ada" aria-label="Permalink to &quot;Baseline: mendokumentasikan perilaku yang sudah ada&quot;">​</a></h2><p>Kalau kamu akan mengubah perilaku yang belum punya spec, tulis dulu spec untuk keadaan sekarang:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deuz:baseline pemesanan-buku</span></span></code></pre></div><p>Agent akan:</p><ol><li>menyepakati cakupan dan bukti yang akan dibaca: handler server, logika bisnis, definisi API, kode UI, file desain, dan test yang ada;</li><li>menulis <code>deuz/specs/pemesanan-buku/spec.md</code> yang menggambarkan apa yang sistem lakukan <strong>hari ini</strong>, dengan nilai contoh yang dihitung dari kode;</li><li><strong>tidak mengarang</strong>. Perilaku yang terlihat seperti bug tidak ditulis sebagai requirement, melainkan dilaporkan sebagai temuan. Hal yang tidak jelas diajukan sebagai pertanyaan untuk analyst.</li></ol><p>Bukti (<code>path:line</code>), pertanyaan, dan temuan ada di laporan agent, <strong>tidak</strong> di dalam spec.</p><p>Setelah baseline ada, perubahan berikutnya ditulis sebagai delta <code>MODIFIED</code> terhadap spec itu.</p><p>Baseline hanya untuk spec yang <strong>belum ada</strong>. Kalau spec-nya sudah ada, perubahan apa pun harus lewat work (<code>/deuz:new</code>).</p><h2 id="kapan-perlu-baseline-kapan-tidak" tabindex="-1">Kapan perlu baseline, kapan tidak <a class="header-anchor" href="#kapan-perlu-baseline-kapan-tidak" aria-label="Permalink to &quot;Kapan perlu baseline, kapan tidak&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situasi</th><th>Perlu baseline?</th></tr></thead><tbody><tr><td>Fitur baru yang tidak menyentuh perilaku lama</td><td>Tidak. Tulis delta <code>ADDED</code></td></tr><tr><td>Mengubah aturan yang belum pernah ditulis</td><td>Ya, untuk capability yang disentuh saja</td></tr><tr><td>Bug fix yang mengembalikan perilaku seharusnya</td><td>Tidak. Jalur engineer, tanpa specs</td></tr><tr><td>Ingin memahami area lama sebelum refactor besar</td><td>Boleh, sebagai alat bantu memahami</td></tr></tbody></table><h2 id="kesalahan-yang-sering-terjadi" tabindex="-1">Kesalahan yang sering terjadi <a class="header-anchor" href="#kesalahan-yang-sering-terjadi" aria-label="Permalink to &quot;Kesalahan yang sering terjadi&quot;">​</a></h2><ul><li><strong>Mencoba mendokumentasikan semuanya sebelum mulai.</strong> Pekerjaan ini tidak pernah selesai dan tidak ada yang membaca hasilnya.</li><li><strong>Menyalin dokumen lama (PRD, spreadsheet) apa adanya ke spec.</strong> Dokumen lama sering berisi rencana yang tidak pernah dibangun. Spec harus menggambarkan kode yang berjalan, jadi baseline membaca kode.</li><li><strong>Menulis perilaku yang diinginkan ke dalam baseline.</strong> Baseline adalah keadaan sekarang. Perubahannya masuk lewat work.</li></ul>',18)])])}const h=e(s,[["render",r]]);export{g as __pageData,h as default};
